    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([7, 7]), fmt([3, 1]), fmt([1, 3]), fmt([5, 5, 5, 5]), fmt([0, 10**9]), fmt([10**9, 10**9, 0, 0]),
             fmt([2, 1, 1, 1]), fmt([1, 1, 1, 2])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for vmax in (2, 5, 50):
            tests.append(fmt([rng.randint(0, vmax) for _ in range(n)]))
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(100000)]))
    tests.append(fmt([10**9 - i % 3 for i in range(100000)]))
    tests.append(fmt(list(range(100000, 0, -1))))
    tests.append(fmt([rng.randint(5, 6) for _ in range(100000)]))
    return tests

